def ul(items):
    return "<ul>" + "".join(f"<li>{i}</li>" for i in items) + "</ul>"


def ol(items):
    return "<ol>" + "".join(f"<li>{i}</li>" for i in items) + "</ol>"


def finish(i, secs, checklist, example, week):
    """Adds the checklist, a worked example, the local plan note, this week's steps and the help note before the short version."""
    last = secs.pop()
    secs += [("Checklist", ul(checklist)), ("An example", f"<p>{example}</p>"), ("How this fits your local plan", PLAN_V[i % 3]),
             ("What to do this week", ol(week)), HELP_V[i % 3], last]
    return secs


